        raise_from(into, e)


def api_call(func, fallback_func=None, errors=Exception):
    """Calls func and handles exceptions using fallback_func.

    If an exception occurs and fallback_func is provided, calls fallback_func(exception).
    Returns the result of func on success or None on failure.
    """
    errors = _ensure_exceptable(errors)
    def wrapper(*args, **kwargs):
        try:
            return func(*args, **kwargs)
        except errors as e:
            if fallback_func is not None:
                return fallback_func(e)
            return None
    return wrapper

